import{_ as r,a as o,b as a}from"./agent-interaction-real-038c1405.js";import{_ as d}from"./plugin-vue_export-helper-c27b6911.js";import{r as l,o as c,c as h,d as t,e,b as i,w as s,a as p,f as u}from"./app-901c4b09.js";const g={},m=t("strong",null,"removing the hub and link roles",-1),b=t("p",null,"As long as there are two node types, there are two tool sets and half the behavior is wrong; every fix creates a new asymmetry.",-1),v=u(`<h2 id="_1-the-wrong-starting-point" tabindex="-1"><a class="header-anchor" href="#_1-the-wrong-starting-point" aria-hidden="true">#</a> 1. The wrong starting point</h2><p>The original model:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>hub  = listens, routes, owns the pending queue
link = connects, replies
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>So the tools split in two:</p><ul><li>hub: <code>peer_ask</code> / <code>peer_send</code> / <code>peer_steer</code> / <code>peer_cancel</code> / <code>peer_pending</code> / <code>peer_bind</code> ...</li><li>link: <code>peer_reply</code> / <code>peer_send</code> / <code>peer_status</code></li></ul><p>Consequences:</p><ul><li>the link cannot <code>peer_ask</code>; it sends and waits for a push</li><li>the link has no <code>peer_pending</code> / <code>peer_inbox</code>, so inbound messages are invisible</li><li>origin is recorded only on the hub; the link cannot reply to it</li></ul><p><strong>A role is a property of one exchange, not of a node</strong>: whoever sends is this exchange&#39;s initiator; whoever receives is its target. The next exchange can reverse.</p><h2 id="_2-one-node" tabindex="-1"><a class="header-anchor" href="#_2-one-node" aria-hidden="true">#</a> 2. One node</h2><figure><img src="`+r+`" alt="One node, one tool set" tabindex="0" loading="lazy"><figcaption>One node, one tool set</figcaption></figure><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>PeerNode
├─ listen?    optional capability
├─ connect?   optional capability
├─ one tool set (12 tools)
├─ origin     local session &lt;-&gt; peer session
├─ binding    chosen once, then fixed
└─ bus        inbox record + pending fallback
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Both entry points construct a <code>PeerNode</code>, wrap the existing transports as capabilities, and call the <strong>same</strong> <code>registerPeerTools</code>.</p><h2 id="_3-one-tool-set" tabindex="-1"><a class="header-anchor" href="#_3-one-tool-set" aria-hidden="true">#</a> 3. One tool set</h2><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>peer_targets / peer_ask / peer_send / peer_reply
peer_steer / peer_cancel / peer_pending / peer_bind
peer_wait / peer_inbox / peer_list / peer_status
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Same names, same parameters, same behavior on both ends. <code>peer</code> may be omitted when a node has a single peer, and <code>text</code> is an alias for <code>prompt</code>.</p><h2 id="_4-bind-once-then-fixed" tabindex="-1"><a class="header-anchor" href="#_4-bind-once-then-fixed" aria-hidden="true">#</a> 4. Bind once, then fixed</h2><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>first send from a local session
  → userQuestions.ask: remote workspace + remote session
  → remember the binding (local session + peer → remote session)
  → no more questions
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>When the conversation already has an <strong>origin</strong> (the peer messaged it), that origin is used and no card appears — an unattended node is never blocked on a picker.</p><h2 id="_5-reverse-capabilities" tabindex="-1"><a class="header-anchor" href="#_5-reverse-capabilities" aria-hidden="true">#</a> 5. Reverse capabilities</h2><p>The hub serves:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>peer/steer   inject into a local session via the session controller
peer/cancel  abort a local session
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>The link&#39;s <code>peer_steer</code> / <code>peer_cancel</code> call those, defaulting to the origin.</p><h2 id="_6-a-lightweight-bus" tabindex="-1"><a class="header-anchor" href="#_6-a-lightweight-bus" aria-hidden="true">#</a> 6. A lightweight bus</h2><p>No full message protocol, only record + fallback:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>inbound message
  → record in inbox (peer_wait / peer_inbox)
  → target present and writable → deliver
  → otherwise → pending (peer_pending / peer_bind)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Every inbound message is recorded; only failed deliveries queue. Nothing is lost, and normal traffic does not pile up.</p><h2 id="_7-perception-queue-or-steer" tabindex="-1"><a class="header-anchor" href="#_7-perception-queue-or-steer" aria-hidden="true">#</a> 7. Perception: queue or steer</h2><p>The most subtle bug. Delivery used <code>sessionController.prompt(mode: &#39;queue&#39;)</code>:</p><ul><li>delivery reported success</li><li>the message waited for the <strong>next</strong> turn</li><li>the running turn never saw it</li><li>the user saw a queued message in the GUI and asked why the agent could not perceive it</li></ul><p>Switched to <code>mode: &#39;steer&#39;</code>: injected at the next step, perceived immediately. When the session is idle, steer starts a turn.</p><p>When a message lands in pending, the hub also notifies the most recently active session:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>[peer] a message from macmini entered pending (id):
...
Use peer_pending to inspect it, then peer_bind to choose a session.
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_8-bugs-fixed-in-this-round" tabindex="-1"><a class="header-anchor" href="#_8-bugs-fixed-in-this-round" aria-hidden="true">#</a> 8. Bugs fixed in this round</h2><table><thead><tr><th>Symptom</th><th>Root cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>peer_reply</code> always reports no origin</td><td><code>PeerNode.origins</code> and the link server&#39;s origins were two maps</td><td><code>originFor</code> falls back to the capability</td></tr><tr><td>targeted replies never reach the inbox</td><td>the targeted branch returned before <code>inbox.push</code></td><td>record inbound before the branch</td></tr><tr><td>queued messages vanished</td><td>auto mode returned <code>delivered:false</code> without enqueueing</td><td>failures join pending and are persisted</td></tr><tr><td>live pending overwritten</td><td><code>hub.test</code> used the real <code>DSH_HOME</code></td><td>tests use a temp directory</td></tr><tr><td><code>peer_send</code> fails validation</td><td>the unified tool required <code>peer</code> + <code>prompt</code>; callers passed <code>text</code></td><td><code>peer</code> optional, <code>text</code> alias</td></tr><tr><td>unattended node blocks</td><td>every send opened the picker</td><td>skip it when an origin exists</td></tr><tr><td>the agent misses queued messages</td><td>inbound used queue</td><td>inbound uses steer</td></tr></tbody></table><h2 id="_9-testing-method-changed-too" tabindex="-1"><a class="header-anchor" href="#_9-testing-method-changed-too" aria-hidden="true">#</a> 9. Testing method changed too</h2><ul><li>unit tests use a temporary <code>DSH_HOME</code>, never the live queue</li><li>integration tests use in-memory transports, not a real peer</li><li>live verification runs once with steps, expectations, and actual output</li><li>no repeated test messages in production conversations</li></ul><h2 id="_10-lessons" tabindex="-1"><a class="header-anchor" href="#_10-lessons" aria-hidden="true">#</a> 10. Lessons</h2><ul><li><strong>Align the model before writing code</strong>: a wrong node type produces patches forever</li><li><strong>Symmetry is not a slogan</strong>: tools, origin, result routing, and errors must be one implementation</li><li><strong>Separate message from delivery</strong>: received ≠ delivered ≠ user-visible</li><li><strong>Leave evidence</strong>: <code>peer-push.log</code>, the pending file, the inbox</li><li><strong>Isolate tests</strong>: a test that writes the real queue destroys real data</li></ul><h2 id="_11-real-examples-from-this-machine" tabindex="-1"><a class="header-anchor" href="#_11-real-examples-from-this-machine" aria-hidden="true">#</a> 11. Real examples from this machine</h2><p>Both diagrams are drawn from local logs, not sketches.</p><figure><img src="`+o+'" alt="The agent loop: a real peer_inbox call" tabindex="0" loading="lazy"><figcaption>The agent loop: a real peer_inbox call</figcaption></figure><p><em>One real turn: <code>turn/start → step/start → assistant/message → tool/call(peer_inbox) → tool/result → step/end → turn/end</code>, followed by the hub pushing the final text back to macmini.</em></p><figure><img src="'+a+'" alt="A real exchange between two agents" tabindex="0" loading="lazy"><figcaption>A real exchange between two agents</figcaption></figure><p><em>macmini&#39;s <code>peer_send</code> enters linux-vm&#39;s <code>session-6883d4db…</code>; the hub records it in the inbox, steers it into the running turn, and pushes the <code>[hub]</code> result back to <code>peer-macmini-fingerbot-file-push</code> at turn end.</em></p>',44);function _(x,f){const n=l("RouterLink");return c(),h("div",null,[t("p",null,[e("The previous two posts covered "),i(n,{to:"/en/architecture/dsh-peer-selection.html"},{default:s(()=>[e("session selection")]),_:1}),e(" and "),i(n,{to:"/en/architecture/dsh-peer-result-push.html"},{default:s(()=>[e("asynchronous result routing")]),_:1}),e(". This one closes the loop: "),m,e(".")]),b,p(" more "),v])}const q=d(g,[["render",_],["__file","dsh-peer-peer-node.html.vue"]]);export{q as default};
